   else{$r=pg_query_params($conn,"SELECT id,attendee_code,full_name,password_hash,status,must_complete_profile FROM attendees WHERE lower(attendee_code)=lower($1)",[$identity]);if($r&&pg_num_rows($r)===1){$a=pg_fetch_assoc($r);if($a['status']!=='active')$error='This attendee account is disabled.';elseif(password_verify($password,$a['password_hash'])){record_login_attempt($conn,$identity,'password',true);session_regenerate_id(true);$_SESSION['attendee_id']=$a['id'];$_SESSION['attendee_code']=$a['attendee_code'];$_SESSION['attendee_name']=$a['full_name'];$_SESSION['must_complete_profile']=$a['must_complete_profile']==='t'||$a['must_complete_profile']===true;$_SESSION['auth_started_at']=time();$_SESSION['last_activity_at']=time();redirect($_SESSION['must_complete_profile']?'attendee/onboarding.php':'attendee/dashboard.php');}else $error='Invalid credentials.';}else $error='Invalid credentials.';}
   if($error)record_login_attempt($conn,$identity,'password',false);
  }}
 }
